UPDATE "team_invitations" SET "expires_at" = "competitions"."registration_end_at" FROM "teams", "competitions" WHERE "teams"."id" = "team_invitations"."team_id" AND "competitions"."id" = "teams"."competition_id" AND "team_invitations"."status" IN ('pending', 'pending_claim') AND "competitions"."status" = 'published' AND "competitions"."deleted_at" IS NULL AND "competitions"."registration_end_at" > now() AND ("teams"."status" = 'forming' OR "team_invitations"."expires_at" > now()) AND "team_invitations"."expires_at" IS DISTINCT FROM "competitions"."registration_end_at";
